// 处理SVG内容，移除固定尺寸属性
function processSvgContent(svgString: string): string {
  if (!svgString) return ''

  // 移除width和height属性，让CSS控制尺寸
  let processedSvg = svgString
    .replace(/width="[^"]*"/g, '')
    .replace(/height="[^"]*"/g, '')
    .replace(/class="[^"]*"/g, 'class="custom-svg"')

  // 确保有viewBox属性
  if (!processedSvg.includes('viewBox')) {
    processedSvg = processedSvg.replace('<svg', '<svg viewBox="0 0 1024 1024"')
  }

  return processedSvg
}

// 计算SVG内容
const processedSvgContent = computed(() => {
  let svgContent = ''

  // 如果提供了SVG代码，直接使用
  if (props.svg) {
    svgContent = props.svg
  }
  // 如果提供了图标名称，从预设库中获取
  else if (props.name) {
    svgContent = iconLibrary[props.name as keyof typeof iconLibrary] || iconLibrary.default
  }
  // 默认图标
  else {
    svgContent = iconLibrary.default
  }

  return processSvgContent(svgContent)
})

// 计算颜色类
const colorClass = computed(() => {
  if (props.color === 'currentColor') {
    return 'text-current'
  }
  return `text-${props.color}`
})
</script>

<style scoped>
.custom-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.custom-icon :deep(svg) {
  width: 100%;
  height: 100%;
}

.custom-icon :deep(.custom-svg) {
  width: 100%;
  height: 100%;
}

/* 尺寸类 */
.w-sm { width: 16px; height: 16px; }
.w-md { width: 20px; height: 20px; }
.w-lg { width: 24px; height: 24px; }
.w-xl { width: 32px; height: 32px; }
.w-2xl { width: 40px; height: 40px; }
.w-3xl { width: 48px; height: 48px; }
</style>
